export const FullActionFragmentDoc = gql`
    fragment FullAction on Action {
  __typename
  ... on ArticleCreatedAction {
    date
    article {
      id
      createdAt
      url
      latest {
        ...ArticleCreatedActionRevision
      }
    }
  }
  ... on PageCreatedAction {
    date
    page {
      id
      createdAt
      url
      latest {
        ...PageCreatedActionRevision
      }
    }
  }
  ... on CommentCreatedAction {
    date
    comment {
      id
      user {
        firstName
        name
      }
      guestUsername
      title
      text
    }
  }
  ... on PollStartedAction {
    date
    poll {
      id
      question
    }
  }
  ... on SubscriptionCreatedAction {
    date
    subscription {
      id
      user {
        firstName
        name
      }
      memberPlan {
        name
      }
    }
  }
  ... on AuthorCreatedAction {
    date
    author {
      id
      name
      jobTitle
    }
  }
  ... on UserCreatedAction {
    date
    user {
      id
      firstName
      name
    }
  }
  ... on EventCreatedAction {
    date
    event {
      id
      name
      location
    }
  }
}
    ${ArticleCreatedActionRevisionFragmentDoc}
${PageCreatedActionRevisionFragmentDoc}`;
